// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);

        // Alice adds 1 ether
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Bob's fallback will reenter addToBalance
        vm.prank(bob);
        (bool successBob, ) = address(c).call{value: 1 ether}(
            abi.encodeWithSignature("withdrawBalance()")
        );

        // Now check divergence: Bob's balance differs
        uint256 bobBalance = c.getBalance(bob);
        // Reference: should be 0 (revert reverts state, balance stays 0)
        // Buggy: Bob's fallback called addToBalance after balance was zeroed, so balance becomes 1 ether
        assertTrue(bobBalance == 1 ether, "Bob's balance should be 1 ether in the buggy version");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Deploy a malicious contract that reenters via fallback
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund attacker with 1 ether
        vm.deal(address(0xAlice), 1 ether);
        vm.prank(address(0xAlice));
        c.addToBalance{value: 1 ether}();

        // Alice transfers 1 ether to Bob
        vm.deal(address(attacker), 0);

        // Bob (attacker) tries to withdraw, triggering fallback
        vm.prank(address(attacker));
        try c.withdrawBalance() {
            // If reference, this reverts because nonReentrant blocks reentrance; if buggy, it succeeds
        } catch {
            // in reference, revert happens
        }

        // Check Bob's balance: reference -> 0, buggy -> 1 ether
        assertTrue(c.getBalance(address(attacker)) == 1 ether, "Bob's balance should be 1 ether in the buggy version");
    }
}

contract ReentrantAttacker {
    C target;
    bool attack;
    constructor(C _target) { target = _target; }

    receive() external payable {
        if (!attack) {
            attack = true;
            target.addToBalance{value: 1 ether}();
        }
    }
}

