pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.addToBalance{value: 1 ether}();
        // Bob's fallback will call addToBalance again
        vm.startPrank(bob);
        (bool success, ) = address(c).call{value: 0}("");
        vm.stopPrank();
        // The fallback doesn't get called from direct call, need withdrawBalance
        vm.startPrank(bob);
        // Reentrancy: Bob's fallback calls addToBalance with 1 ether
        // Setup: Deploy a contract with fallback that calls addToBalance
        // We'll use a contract to simulate
        Reentrant attacker = new Reentrant(c);
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        c.addToBalance{value: 1 ether}();
        // Now attacker withdraws, triggering fallback
        vm.prank(address(attacker));
        c.withdrawBalance();
        uint bal = c.getBalance(address(attacker));
        // Reference: 0 (revert in withdrawBalance? Actually reference reverts, so bal stays 1? Need to check)
        // In reference, nonReentrant prevents reentrancy, so fallback reverts, then withdrawBalance reverts fully, balance unchanged = 1
        // In buggy, set balance to 0 first, then fallback succeeds, adds 1, so final balance = 1
        // So both give 1? That's not a difference. Need different scenario.
        // Let's adjust: use Alice and Bob directly with fallback
    }
}

contract Reentrant {
    C public c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        if (address(c).balance >= 1 ether) {
            c.addToBalance{value: 1 ether}();
        }
    }
    function attack() external {
        c.withdrawBalance();
    }
}

