pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that reenters via fallback
        Reenterer reenterer = new Reenterer(c);
        address alice = address(0x1111);
        address bob = address(reenterer);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();
        // Bob (reenterer) withdraws; his fallback calls addToBalance with 1 ether
        vm.deal(bob, 0);
        vm.prank(bob);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, reentrancy reverts, so ok = false and bob's balance = 0
        // In the buggy version, reentrancy succeeds, so ok = true and bob's balance = 1 ether
        // We assert that the call reverts (reference behavior)
        assertTrue(!ok && c.getBalance(bob) == 0);
    }
}

contract Reenterer {
    C c;
    constructor(C _c) {
        c = _c;
    }
    receive() external payable {
        if (address(this).balance >= 1 ether) {
            c.addToBalance{value: 1 ether}();
        }
    }
}

