pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a reentrant attacker contract
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address alice = address(0x1234);
        address bob = address(attacker);

        // Give Alice 1 ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Give attacker 1 ether for the reentrant call
        vm.deal(bob, 1 ether);

        // Bob (attacker) withdraws; this triggers the fallback which calls addToBalance
        vm.prank(bob);
        c.withdrawBalance();

        // After the call, in the reference attacker's balance is 0, in buggy it's 1 ether
        // The reference reverts due to nonReentrant, so attacker's balance stays 0
        // For buggy, balance set to 0 before call, then reentrant call adds 1 ether
        // Because the attacker's fallback adds 1 ether BEFORE the revert check, balance ends 1 ether
        // But the reference reverts the whole withdrawal, so nothing changes
        // We can't catch revert here because the withdraw did revert in reference?
        // Actually in reference, when attacker withdraws, their balance is 0, so send 0 ether,
        // the call succeeds, no reentrancy (no value sent), then balance set to 0 (already 0).
        // That's not the scenario we want.
        // We need attacker to have non-zero balance BEFORE withdrawal to trigger the difference.
        // Let's adjust: first, Alice gives Bob some balance via addToBalance? No, addToBalance uses msg.value.
        // So we need Bob to have deposited before.
        // Reset:
        c = new C();
        attacker = new ReentrantAttacker(c);
        alice = address(0x1234);
        bob = address(attacker);

        // Alice deposits 1 ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Bob deposits 1 ether via the attacker contract
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.addToBalance{value: 1 ether}();

        // Now Bob's balance = 1 ether. Bob withdraws; his fallback is called with 1 ether value.
        // The fallback calls addToBalance with 1 ether from the contract's own balance?
        // Actually the attacker contract must have ether to send. The attacker has 0 ether now.
        // The call from c sends 1 ether to attacker contract, so attacker contract receives 1 ether.
        // In the fallback, we call addToBalance with that 1 ether.
        // So in reference: nonReentrant blocks the reentrant addToBalance, reverts entire withdrawal,
        // Bob's balance stays 1 ether.
        // In buggy: balance set to 0 before call, call succeeds (attacker gets 1 ether),
        // then fallback calls addToBalance with 1 ether, which adds 1 to Bob's balance (now 1 ether).
        // But wait: the buggy version sets balance to 0, then external call, then after fallback,
        // the code does not set balance again (since it's already 0). So final balance = 1 ether.
        // The reference: balance stays 1 ether because revert.
        // So they are equal? No, reference reverts external call, so userBalance[Bob] = 1 ether (unchanged).
        // Buggy: userBalance[Bob] = 1 ether (0 + 1 from reentrant). So they are the same!
        // That's not divergence.
        // We need a case where buggy ends with balance != reference.
        // In buggy, after external call, the code does NOT revert (since it checks success flag).
        // But if fallback reverts, buggy reverts too. The reference reverts anyway.
        // So we need a scenario where buggy succeeds and reference reverts, and the final balance differs.
        // Consider: Alice deposits 1 ether. Bob (attacker) with 0 balance withdraws.
        // Reference: sends 0 ether, call succeeds (no reentrancy), balance = 0.
        // Buggy: sets balance to 0, sends 0 ether (userBalance[msg.sender] is now 0), call succeeds,
        // fallback calls addToBalance with 0 ether... no change. Still same.
        // Need a non-zero balance where the external call sends ether and the fallback adds to balance.
        // The difference is that in buggy, the balance is set to 0 BEFORE the call, so the call sends 0,
        // while reference sends the original balance. But the reentrant call then adds to the zeroed balance.
        // So final balance in buggy = amount added in reentrant call; in reference = original balance (since revert).
        // For divergence, after the withdrawal attempt, buggy balance = reentrant amount, reference = original.
        // Let's set original balance = 1 ether, reentrant amount = 1 ether.
        // Reference: reverts, balance stays 1 ether.
        // Buggy: balance set to 0, sends 0 ether (since balance now 0), call succeeds? No, the call sends value
        // equal to userBalance[msg.sender] which is 0 at that point, so no ether sent, fallback receives 0.
        // Then fallback sends 1 ether? The attacker contract must have ether to send. It doesn't.
        // So fallback does nothing, balance = 0. Divergence: reference 1, buggy 0. That works!
        // But the reentrant addToBalance requires msg.value. If fallback sends 0, balance stays 0.
        // We need attacker to have ether to send. The attacker can have ether beforehand.
        // So: give attacker contract 1 ether via vm.deal(bob, 1 ether) before withdrawal.
        // Then: bob withdraws (balance = 1). Buggy: sets balance to 0, sends 0 ether (since balance 0),
        // call to attacker contract with value 0, fallback calls addToBalance{value: 1 ether}() using the contract's own ether.
        // That adds 1 ether to bob's balance (now 1). Final: 1.
        // Reference: sends 1 ether (balance 1), call to attacker with value 1, fallback calls addToBalance{value: 1 ether},
        // but nonReentrant reverts, so the entire withdrawBalance reverts, balance stays 1.
        // Final: reference 1, buggy 1. Same again.
        // Need a case where the reentrant amount differs from original balance.
        // Let original = 2, reentrant = 1: Reference reverts -> balance stays 2. Buggy: set to 0, send 0, fallback adds 1 -> 1.
        // So divergence: 2 vs 1.
        // Let's implement: Alice deposits 2 ether, then attacker (Bob) deposits 2 ether? No, attacker's balance is set by addToBalance.
        // Simpler: just use vm.deal to give the attacker contract ether, and have the reference deposit via Alice.
        // Actually we need attacker's balance in the contract to be 2. So Alice calls addToBalance for attacker? No, it uses msg.sender.
        // We need Bob (attacker) to call addToBalance with 2 ether first.
        // Then Bob withdraws. Reference: sends 2 ether to attacker, reentrant call (with 1 ether from attacker's own balance) reverts, balance = 2.
        // Buggy: set balance to 0, sends 0, reentrant call adds 1, balance = 1.
        // That's divergence.
        // Let's code it:
        c = new C();
        attacker = new ReentrantAttacker(c);
        alice = address(0x1234);
        bob = address(attacker);

        // Bob deposits 2 ether
        vm.deal(bob, 2 ether);
        vm.prank(bob);
        c.addToBalance{value: 2 ether}();

        // Give attacker contract 1 ether for the reentrant call
        vm.deal(bob, 1 ether); // bob is the attacker contract address, so this gives it ether
        // Actually vm.deal works on addresses. We need to give the contract ether.
        // attacker contract address is bob. So vm.deal(bob, 1 ether) gives it 1 ether.

        // Bob withdraws
        vm.prank(bob);
        c.withdrawBalance();

        // Check balances: in reference, revert -> balance stays 2. In buggy, balance = 1.
        // But we need to know which version we are testing? We are testing the deployed c (which is the one in setUp).
        // Actually the test must pass on reference and fail on buggy.
        // The test code is the same, but we run it on two different contracts (reference and buggy).
        // So the assertion must hold on reference and fail on buggy.
        // Here, on reference, balance = 2 (since revert). On buggy, balance = 1.
        // So we assert that balance == 2? That would pass on reference, fail on buggy.
        // But careful: in reference, the withdrawal reverts, so the call to c.withdrawBalance() reverts.
        // Our test will revert! We need to catch the revert.
        // In reference, the withdrawBalance will revert due to nonReentrant (inside the call).
        // So the entire external call reverts, and the test will fail because the call reverts.
        // To catch, we use try/catch.
        // Let's do:
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        // In reference, ok = false; in buggy, ok = true.
        // Then we can assert that ok == false (reference passes) and actually check balance.
        // But the assertion should be a single assertTrue.
        // We can assert that ok == false balances something.
        // After the call, in reference, balance unchanged (2). In buggy, balance = 1.
        // So we can assert that c.getBalance(bob) == 2 (on reference) vs 1 on buggy.
        // But on reference, the call reverts, so the state is unchanged => getBalance(bob) == 2.
        // On buggy, it doesn't revert, so getBalance(bob) == 1.
        // So we assert: c.getBalance(bob) == 2. That passes on reference, fails on buggy.
        // But wait: on reference, the catch block will exec, and we still check getBalance.
        // It should be 2.
        assertTrue(c.getBalance(bob) == 2);
    }
}

contract ReentrantAttacker {
