// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x111);
        address bob = address(0x222);

        vm.deal(alice, 10 ether);
        vm.deal(bob, 2 ether);

        vm.prank(alice);
        c.addToBalance{value: 5 ether}();

        vm.prank(bob);
        c.addToBalance{value: 2 ether}();

        // Bob calls withdrawBalance() from within alice's reentrant addToBalance()
        // We need a reentrant call: alice calls addToBalance() again, but with a contract that
        // reenters into withdrawBalance for bob.
        // Since we cannot deploy a malicious contract in this simple test, we simulate:
        // The reentrancy can only happen if addToBalance is not protected (buggy version).
        // In the reference version (with nonReentrant), addToBalance is protected, so no reentrancy.
        // So we simply check that after alice adds again, the balance differs.

        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        uint256 balRef = 6 ether; // alice should have 5+1 = 6 in reference (nonReentrant prevents any reentrancy)
        uint256 balBug = 0; // buggy version would allow reentrancy draining alice's balance

        // Actually, since we cannot trigger the reentrancy without a malicious contract,
        // we need a different scenario: The bug reintroduces the classic reentrancy where
        // withdrawing before the balance reset allows draining.

        // Simpler: Let alice deposit, then alice calls withdrawBalance(). In the reference,
        // nonReentrant on withdrawBalance prevents reentrancy. But the mutant only removes
