pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);

        // Alice deposits 1 ether
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();
        // Bob deposits 2 ether
        vm.prank(bob);
        c.addToBalance{value: 2 ether}();

        // Bob starts a withdrawal; inside, he reenters addToBalance with 2 ether
        // The reentrancy is only possible if nonReentrant is missing
        vm.startPrank(bob);
        (bool success, ) = address(c).call{value: 2 ether}(abi.encodeWithSignature("withdrawBalance()"));
        vm.stopPrank();

        // In the reference, the reentrancy fails and Bob's final balance is 0 (withdrawn)
        // In the buggy version, the reentrancy succeeds; Bob's balance becomes 2 (from reentry) plus 2 (original) = 4
        bool buggyVersion = (c.getBalance(bob) == 4 ether);
        assertTrue(buggyVersion);
    }
}

