contract Reenter {
    C public target;
    bool public reentered;

    constructor(address _target) {
        target = C(_target);
        reentered = false;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.addToBalance{value: 2 ether}();
        }
    }
}

