import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    receive() external payable {}

    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(address(this), 2 ether);

        // First deposit by the test contract itself (so we control the callback)
        vm.prank(address(this));
        c.addToBalance{value: 1 ether}();

        // Now the test contract has balance 1 inside c.
        // The test contract calls withdrawBalance, which sends 1 ether to the test contract.
        // When the test contract receives the 1 ether, its receive function is triggered.
        // The receive function (above) will reenter addToBalance with the same 1 ether.
        // In the reference, this reentrant call reverts due to nonReentrant check.
        // In the bug, it succeeds, adding another 1 ether to the test contract's balance.
        // After the reentrant call returns, the outer withdrawBalance sets the balance to 0.
        // So final: reference: balance remains 1 (because the outer call reverted) bug: balance 0 (because outer succeeded and set to 0).

        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));

        // Check balance
        uint256 finalBalance = c.getBalance(address(this));
        // Reference: balance = 1 (revert prevented any change)
        // Bug: balance = 0
        assertTrue(finalBalance == 1, "Expected balance to be 1 in reference");
    }
}

